+        } else {
+            currentContentLength += msg.content().readableBytes();
+            if (currentContentLength > maxContentLength) {
+                msg.release();
+                ctx.writeAndFlush(TOO_LARGE_CLOSE.retainedDuplicate()).addListener(ChannelFutureListener.CLOSE);
