+            taskManager.cancelTaskAndDescendants(groupTask, reason, true, ActionListener.running(() -> {
+                EsqlCCSUtils.skipUnavailableListener(delegate, executionInfo, clusterAlias, EsqlExecutionInfo.Cluster.Status.PARTIAL)
